// ============================================================================
// SUBJECT REGISTRY INDEX: finds every subject-grade entry and writes the two small generated files the app reads.
//   npm run registry            writes them
//   npm run registry -- --check exits 1 if they are out of date (tests/registry.test.mjs runs this)
//
// An entry is one file: src/ai-tutor/content/subjects/<subject>_g<N>.js (default export, see docs/adding-a-subject.md).
// Adding a subject-grade = adding that file, then running this. The two outputs (one line per entry, merge=union in
// .gitattributes) are the only generated joins:
//   src/ai-tutor/content/subjects/index.generated.js   the entries, imported by registry.js
//   src/learner/subjects.generated.js                  the light list of ids and code prefixes (no imports: the edge
//                                                      functions and mastery.js read it)
//   src/ai-tutor/content/subjects/strip.generated.js        which family files a phone build drops while their signed list is empty
// ============================================================================
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const dir = resolve(root, 'src/ai-tutor/content/subjects');
const files = readdirSync(dir).filter(f => /^[a-z][a-z0-9_]*_g\d+\.js$/.test(f)).sort();

const entries = [];
for (const f of files) entries.push({ file: f, def: (await import(pathToFileURL(resolve(dir, f)).href)).default });

const problems = [];
const seen = new Set();
for (const { file, def } of entries) {
  const want = `${def?.subject}_g${def?.grade}.js`;
  if (!def) { problems.push(`${file}: no default export`); continue; }
  if (want !== file) problems.push(`${file}: the file name must be <subject>_g<grade>.js, i.e. ${want}`);
  if (seen.has(want)) problems.push(`${file}: duplicate subject-grade`);
  seen.add(want);
}
// One code prefix per subject, one subject per prefix.
const prefixOf = new Map();
for (const { file, def } of entries) {
  if (!def) continue;
  if (prefixOf.has(def.subject) && prefixOf.get(def.subject) !== def.prefix) problems.push(`${file}: subject ${def.subject} already uses prefix ${prefixOf.get(def.subject)}`);
  prefixOf.set(def.subject, def.prefix);
}
const bySubjectPrefix = new Map();
for (const [s, p] of prefixOf) { if (bySubjectPrefix.has(p) && bySubjectPrefix.get(p) !== s) problems.push(`prefix ${p} is used by ${bySubjectPrefix.get(p)} and ${s}`); bySubjectPrefix.set(p, s); }
if (problems.length) { console.error(problems.join('\n')); process.exit(1); }

const HEAD = 'GENERATED by scripts/build-subject-registry.mjs (npm run registry). Do not edit.';
// One item per line, trailing commas: two builders adding different subject-grades merge cleanly (merge=union in .gitattributes);
// after a merge run npm run registry (tests/registry.test.mjs fails while the files are stale).
const index = `// ${HEAD}
${entries.map(e => `import ${e.file.replace('.js', '')} from './${e.file}';`).join('\n')}
export const ENTRIES = [
${entries.map(e => `  ${e.file.replace('.js', '')},`).join('\n')}
];
`;

// Maths is not an entry (its graph is the knowledge graph); it comes first. Subjects follow by their `order` (default 100), then name.
const order = [...new Set(entries.map(e => e.def.subject))];
const orderOf = (s) => entries.find(e => e.def.subject === s).def.order ?? 100;
order.sort((a, b) => orderOf(a) - orderOf(b) || a.localeCompare(b));
const ids = ['math', ...order];
const prefixes = { MATH: 'math', ...Object.fromEntries(order.map(s => [prefixOf.get(s), s])) };
const light = `// ${HEAD} No imports: read by the browser,
// the edge functions and mastery.js. Which subjects exist and the prefix of each one's curriculum skill codes.
export const SUBJECT_IDS = [
${ids.map(i => `  '${i}',`).join('\n')}
];
export const SUBJECT_PREFIXES = {
${Object.entries(prefixes).map(([k, v]) => `  ${k}: '${v}',`).join('\n')}
};
`;

// A phone build replaces each family file with an empty list while its signed list (families/<signedFile>) is empty; vite.config.js
// reads the signed file itself, so signing a family needs no regeneration.
const strip = `// ${HEAD} Family file -> its signed list file.
export default {
${entries.flatMap(e => (e.def.familyFiles || []).map(f => `  '${f}': '${e.def.signedFile}',`)).sort().join('\n')}
};
`;

const outputs = [
  ['src/ai-tutor/content/subjects/index.generated.js', index],
  ['src/learner/subjects.generated.js', light],
  ['src/ai-tutor/content/subjects/strip.generated.js', strip],
];
if (process.argv.includes('--check')) {
  const stale = outputs.filter(([p, t]) => !existsSync(resolve(root, p)) || readFileSync(resolve(root, p), 'utf8') !== t).map(([p]) => p);
  if (stale.length) { console.error(`Subject registry out of date: ${stale.join(', ')}. Run: npm run registry`); process.exit(1); }
  console.log(`subject registry up to date: ${entries.length} subject-grade entries`);
} else {
  for (const [p, t] of outputs) writeFileSync(resolve(root, p), t);
  console.log(`subject registry: ${entries.length} entries (${files.join(', ')})`);
}
